def secondLargest(arr):
    if (len(arr) < 2):
        return None
        # or error
    largest = float('-inf')
    second = float('-inf')
    for num in arr:
        if (num > largest):
            second = largest
            largest = num
        elif ((num > second) and (num != largest)):
            second = num
    return second
